#!/usr/bin/env bash
# C6.30: write the schema-1 licence manifest and build identity for the
# materials generated by make-sources.sh, after the build (the identity binds the
# real application binary and the pinned SDL2 library). Prints the manifest
# SHA-256 on stdout. The gate itself is packaging/license-bundle.sh.
#
#   write-manifest.sh --materials DIR --platform linux|windows --commit SHA \
#       --source-info application-source.json --application FILE \
#       --sdl2-sha256 HEX --toolchain TEXT --flags TEXT [--mingw-version TEXT]
#       [--runtime-lock sources.lock --runtime-sha256 HEX]    (C6.50: AppImage publication)
set -euo pipefail
source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/common.sh"
exec python3 - "$OD_VERSION" "$OD_PIN_SDL_VERSION" "$@" <<'PY'
import argparse, hashlib, json, sys, tarfile
from pathlib import Path

version, sdl_version = sys.argv[1], sys.argv[2]
parser = argparse.ArgumentParser()
for name in ['--materials', '--platform', '--commit', '--source-info', '--application',
             '--sdl2-sha256', '--toolchain', '--flags']:
    parser.add_argument(name, required=True)
parser.add_argument('--mingw-version')
parser.add_argument('--runtime-lock')
parser.add_argument('--runtime-sha256')
args = parser.parse_args(sys.argv[3:])
root = Path(args.materials)
info = json.loads(Path(args.source_info).read_text())
if info['commit'] != args.commit:
    sys.exit('error: write-manifest: sources are of %s, not %s' % (info['commit'], args.commit))


def pin(rel):
    return {'path': rel, 'sha256': hashlib.sha256((root / rel).read_bytes()).hexdigest()}


def component(name, ver, licence, source, member, kind):
    return {'name': name, 'version': ver, 'license': licence, 'notice': pin('notices/%s.txt' % name),
            'source': pin(source), 'version_member': member, 'version_text': ver, 'version_kind': kind}


sdl_member = 'SDL2-%s/include/SDL_version.h' % sdl_version
v = info['versions']
components = [
    component('application', version, 'GPL-3.0-or-later', 'sources/application.tar.xz',
              '%s/CMakeLists.txt' % info['prefix'], 'CMake-project'),
    component('SDL2', sdl_version, 'Zlib', 'sources/SDL2.tar.xz', sdl_member, 'SDL2-header'),
    component('SDL2-embedded', sdl_version, 'SunPro AND BSD-3-Clause AND MIT AND Zlib AND Apache-2.0',
              'sources/SDL2.tar.xz', sdl_member, 'SDL2-header'),
    component('cJSON', v['cJSON'], 'MIT', 'sources/cJSON.tar.xz', 'cJSON-%s/cJSON.h' % v['cJSON'], 'cJSON-header'),
    component('stb_image', v['stb_image'], 'MIT', 'sources/stb_image.tar.xz',
              'stb_image-%s/stb_image.h' % v['stb_image'], 'stb-header'),
    component('stb_image_write', v['stb_image_write'], 'MIT', 'sources/stb_image_write.tar.xz',
              'stb_image_write-%s/stb_image_write.h' % v['stb_image_write'], 'stb-header'),
    component('stb_truetype', v['stb_truetype'], 'MIT', 'sources/stb_truetype.tar.xz',
              'stb_truetype-%s/stb_truetype.h' % v['stb_truetype'], 'stb-header'),
    component('Inter', v['Inter'], 'OFL-1.1', 'sources/Inter.tar.xz',
              'Inter-%s/VERSION' % v['Inter'], 'literal'),
]
if args.platform == 'windows':
    if not args.mingw_version:
        sys.exit('error: write-manifest: --mingw-version is required for windows')
    components.append({
        'name': 'mingw-w64-runtime', 'version': args.mingw_version,
        'license': 'ZPL-2.1 AND LicenseRef-PublicDomain AND LicenseRef-Lucent-gdtoa AND BSD-3-Clause '
                   'AND LicenseRef-Keith-Marshall AND LicenseRef-SunPro AND GCC-exception-3.1',
        'notice': pin('notices/mingw-w64-runtime.txt'),
        'source': {'not_shipped': 'ZPL-2.1, public-domain, Lucent, BSD-3-Clause, Keith Marshall, SunPro '
                                  'and the GCC Runtime Library Exception require notices for '
                                  'binaries, not source; the '
                                  'exact Debian/Ubuntu packages are named in the notice.'},
        'version_text': args.mingw_version, 'version_kind': 'declared'})
# C6.50: the AppImage Type-2 runtime and the libraries statically linked into it. Their sources
# are the upstream tarballs under sources/appimage-runtime/<name> (materials.sh); each version is
# proved by the gate in the member named here, not taken from the lock file.
RUNTIME = {
    'type2-runtime': ('LICENSE', 'git-archive-commit', None),
    'libfuse': ('meson.build', 'regex', r"project\('libfuse3'.*?version:\s*'(\d+)\.(\d+)\.(\d+)'"),
    'squashfuse': ('configure.ac', 'regex', r"AC_INIT\(\[squashfuse\],\s*\[(\d+)\.(\d+)\.(\d+)\]"),
    'zstd': ('lib/zstd.h', 'regex', r"#define\s+ZSTD_VERSION_MAJOR\s+(\d+).*?#define\s+ZSTD_VERSION_MINOR\s+(\d+)"
                                    r".*?#define\s+ZSTD_VERSION_RELEASE\s+(\d+)"),
    'zlib': ('zlib.h', 'regex', r'#define\s+ZLIB_VERSION\s+"(\d+)\.(\d+)\.(\d+)"'),
    'mimalloc': ('cmake/mimalloc-config-version.cmake', 'regex',
                 r"set\(mi_version_major (\d+)\)\s*set\(mi_version_minor (\d+)\)\s*set\(mi_version_patch (\d+)\)"),
    'musl': ('VERSION', 'literal', None),
}
if bool(args.runtime_lock) != bool(args.runtime_sha256):
    sys.exit('error: write-manifest: --runtime-lock and --runtime-sha256 go together')
if args.runtime_lock:
    locked = {}
    for line in Path(args.runtime_lock).read_text().splitlines():
        if line and not line.startswith('#'):
            name_, ver_, _sha, _file, _url, lic_ = line.split('\t')
            locked[name_] = (ver_, lic_)
    if set(locked) != set(RUNTIME):
        sys.exit('error: write-manifest: sources.lock components %s are not %s' % (sorted(locked), sorted(RUNTIME)))
    for name_, (member_, kind_, regex_) in RUNTIME.items():
        ver_, lic_ = locked[name_]
        source_ = 'sources/appimage-runtime/' + name_
        with tarfile.open(root / source_) as archive_:
            top_ = archive_.getmembers()[0].name.split('/')[0]
        entry_ = component(name_, ver_, lic_, source_, '%s/%s' % (top_, member_), kind_)
        entry_['version_text'] = ver_
        if regex_:
            entry_['version_regex'] = regex_
        components.append(entry_)
artifacts = {'application': hashlib.sha256(Path(args.application).read_bytes()).hexdigest(),
             'SDL2': args.sdl2_sha256}
identity = {'artifacts': artifacts,
            'versions': {c['name']: c['version'] for c in components},
            'application_commit': args.commit,
            'toolchain': args.toolchain, 'flags': args.flags,
            'linkage': {'SDL2': 'shared-substitutable'}}
if args.runtime_lock:
    identity['artifacts']['type2-runtime'] = args.runtime_sha256
    identity['linkage']['libfuse'] = 'static'
(root / 'identity.json').write_text(json.dumps(identity, indent=2, sort_keys=True) + '\n')
manifest = {'schema': 1, 'application_commit': args.commit, 'components': components,
            'identity': pin('identity.json'), 'relink': pin('RELINK.txt'),
            'relink_materials': pin('sources/relink-materials.tar.xz')}
data = (json.dumps(manifest, indent=2, sort_keys=True) + '\n').encode()
(root / 'manifest.json').write_bytes(data)
print(hashlib.sha256(data).hexdigest())
PY
